    if(u.pathname.endsWith("/api/communities"))return DashboardData.searchCommunities(p);
    if(u.pathname.endsWith("/api/community"))return DashboardData.communityDetail(p);
    if(u.pathname.endsWith("/api/community-heatmap"))return DashboardData.communityHeatmap(p);
    if(u.pathname.endsWith("/api/community-locations"))return fetchJSON("./data/community-locations.json");
    if(u.pathname.endsWith("/api/analyze"))return DashboardData.analyze(p);
