function searchCommunityPosition(placeSearch,row,query){return new Promise(resolve=>{
  const timer=setTimeout(()=>resolve({status:"error",message:"高德定位请求超时，已暂停自动重试"}),15000);
  placeSearch.search(query,(status,data)=>{clearTimeout(timer);if(status!=="complete"){resolve({status:status==="no_data"?"not_found":"error",message:data?.info||"高德定位服务暂不可用"});return}
    const pois=data?.poiList?.pois||[],poi=pois.slice().sort((a,b)=>heatmapPoiScore(b,row)-heatmapPoiScore(a,row))[0];
    if(!poi?.location||heatmapPoiScore(poi,row)<17){resolve({status:"not_found"});return}
    const location={name:poi.name||row.community,address:[poi.pname,poi.cityname,poi.adname,poi.address].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(" "),lng:Number(poi.location.lng),lat:Number(poi.location.lat),query};
    resolve(heatmapLocationValid(location)?{location}:{status:"not_found"});
  });
})}
