async function fillMissingHeatmapLocations(rows,locations,requestId){
  const missing=rows.filter(row=>!locationStore.reusable(locationStore.read(row)));
  if(!missing.length||locationStore.paused())return;
  const placeSearch=new state.amap.PlaceSearch({city:"北京",citylimit:true,pageSize:8,pageIndex:1,extensions:"all"});let requests=0;
  for(const row of missing){if(requestId!==state.heatmapRequestId||locationStore.paused())break;
    const result=await locateHeatmapCommunity(placeSearch,row);if(!result.cached)requests++;
    if(requestId!==state.heatmapRequestId)return;
    const located=renderCommunityHeatmapLayers(rows,locations);
    setHeatmapStatus(heatmapCacheStatus(rows,located,requests));
    if(result.status==="error"||result.status==="paused")break;
    await new Promise(resolve=>setTimeout(resolve,400));
  }
}
